The code the comment above describes, cut from my local precheck.py with comments and mask_code's docstring shortened or dropped and the per-draft lines dedented. What is not shown is unchanged from the shipped gate, apart from the print-to-say swap the code notes.

```python
FENCE_OPEN = re.compile(r"^ {0,3}(`{3,}|~{3,})(.*)$")
FENCE_CLOSE = re.compile(r"^ {0,3}(`{3,}|~{3,})[ \t]*$")
CODE_SPAN = re.compile(r"(?<!`)(`+)(?!`)((?:(?!\n[ \t]*(?:\n|\Z|>|#{1,6}[ \t\n]|[-+*][ \t]|\d{1,9}[.)][ \t]|[-*_=]{3,})).)+?)(?<!`)\1(?!`)", re.S)

def mask_code(t):
    out, pos, fence = list(t), 0, None
    def blank(lo, hi):
        for i in range(lo, hi):
            if out[i] != "\n":
                out[i] = " "
    for ln in t.split("\n"):
        end = pos + len(ln)
        if fence is None:
            m = FENCE_OPEN.match(ln)
            if m and not (m.group(1)[0] == "`" and "`" in m.group(2)):
                fence = (m.group(1)[0], len(m.group(1)), pos)
        else:
            m = FENCE_CLOSE.match(ln)
            if m and m.group(1)[0] == fence[0] and len(m.group(1)) >= fence[1]:
                blank(fence[2], end); fence = None
        pos = end + 1
    if fence:
        blank(fence[2], len(t))
    s = "".join(out)
    return CODE_SPAN.sub(lambda m: " " * (m.end() - m.start()), s)

# inside the loop over drafts, for each draft name d and body t:
# three masks, and every run any one finds is checked
masks = [mask_code(t), re.sub(r"`{3}.*?`{3}", lambda m: " " * (m.end() - m.start()), t, flags=re.S),
         re.sub(r"^[ \t]{0,3}`{3}[^\n]*\n.*?(?:^[ \t]{0,3}`{3}[ \t]*$|\Z)", lambda m: " " * (m.end() - m.start()), t, flags=re.S | re.M)]
for masked in masks:
    if masked.count('*"') != masked.count('"*'):
        print("  WARN [%s] %d '*\"' vs %d '\"*' - a stray delimiter can hide a "
              "citation; every quoted span is swept below" % (d, masked.count('*"'), masked.count('"*')))
        break
strict, found = [], set()
for i, masked in enumerate(masks):
    # the mask says where a quotation is; the draft says what it says
    runs = [(t[m.start(1):m.end(1)], m.start(), m.end())
            for m in re.finditer(r'\*"(.+?)"\*', masked, re.S)
            if "*" not in m.group(1).replace("**", "")]
    pos, lines = 0, masked.split("\n")
    run, start = [], None
    for ln in lines + [""]:
        if ln.startswith(">"):
            if start is None:
                start = pos
            run.append(t[pos:pos + len(ln)][1:].lstrip())
        elif run:
            runs.append((" ".join(run), start, pos))
            run, start = [], None
        pos += len(ln) + 1
    for r in runs:
        if r not in found:
            found.add(r)
            strict.append(r + (i,))
for q, lo, hi, i in strict:
    nq = norm(q)
    tag = "  (not shown by mask_code)" if i else ""
    say = lambda line, tag=tag: print(line + tag)
    # verdicts as before, printed through say (c50743 only assigns verdict)
seen = [norm(q) for q, _, _, _ in strict]
swept = []
for masked in masks:
    for m in re.finditer(r'"([^"]{20,})"', masked, re.S):
        if t[m.start(1):m.end(1)] not in swept:
            swept.append(t[m.start(1):m.end(1)])
for q in swept:
    nq = norm(q)
    if any(nq in s for s in seen):
        continue
    where = [k for k, v in ncorpus.items() if nq in v]
    if where:
        print("  SWEEP [%s] unpaired, verbatim in %s: %s"
              % (d, srcs(where), nq[:70]))
    else:
        print("  UNVERIFIED [%s] not found in any cited body: %s" % (d, nq[:90]))
```

